sys_ws_operation.operation_script:
(function process(request, response) {

    try {

        // =====================================================
        // READ REQUEST BODY
        // =====================================================
        var body = request.body.data || {};

        var summary =
            body.summary || {};

        var period =
            body.period || {};

        var employees =
            body.employees || [];


        if (!body.summary) {

            response.setStatus(400);

            response.setBody({
                success: false,
                message: 'Attendance summary data is required.'
            });

            return;
        }


        // =====================================================
        // BUILD SMARTATTEND AI PROMPT
        // =====================================================
        var prompt = '';

        prompt +=
            'You are SmartAttend AI, an attendance analytics assistant for managers.\n\n';

        prompt +=
            'Analyze only the verified attendance data provided below.\n';

        prompt +=
            'Do not invent causes, personal circumstances, medical information, ' +
            'or missing facts.\n';

        prompt +=
            'Do not recommend termination, punishment, disciplinary action, ' +
            'salary changes, PIPs, or other employment decisions.\n';

        prompt +=
            'Recommend only verification, discussion, schedule review, attendance review, ' +
            'and reasonable manager follow-up.\n';

        prompt +=
            'Clearly separate observed facts from recommendations.\n';

        prompt +=
            'Treat small datasets cautiously.\n';

        prompt +=
            'Keep the complete response below 150 words.\n';

        prompt +=
            'Return plain text only. Do not use markdown headings or tables.\n\n';


        prompt +=
            'Manager: ' +
            gs.getUserDisplayName() +
            '\n';


        prompt +=
            'Period: ' +
            (period.from || '') +
            ' to ' +
            (period.to || '') +
            '\n\n';


        prompt +=
            'TEAM SUMMARY:\n' +
            JSON.stringify(summary) +
            '\n\n';


        prompt +=
            'EMPLOYEE STATISTICS:\n' +
            JSON.stringify(employees) +
            '\n\n';


        prompt +=
            'Provide:\n' +
            '1. A concise team attendance observation.\n' +
            '2. Important attendance patterns that may need manager attention.\n' +
            '3. Up to three practical non-disciplinary recommendations.';


        // =====================================================
        // CREATE GEMINI REST MESSAGE
        // =====================================================
        var gemini =
            new sn_ws.RESTMessageV2(
                'SmartAttend Gemini',
                'generate'
            );

			var geminiApiKey =
			new global.SmartAttendGeminiSecret()
				.getApiKey();

			if (!geminiApiKey) {

    response.setStatus(200);

    response.setBody({
        success: false,
        fallback: true,
        message: 'Gemini API key is not configured.'
    });

    return;
}

gemini.setRequestHeader(
    'Content-Type',
    'application/json'
);

gemini.setRequestHeader(
    'x-goog-api-key',
    geminiApiKey
);

		if (!geminiApiKey) {

			response.setStatus(200);

			response.setBody({
				success: false,
				fallback: true,
				message: 'Gemini API key is not configured.'
			});

			return;
		}

		gemini.setRequestHeader(
			'Content-Type',
			'application/json'
		);

		gemini.setRequestHeader(
			'x-goog-api-key',
			geminiApiKey
		);


        // =====================================================
        // BUILD VALID GEMINI JSON
        // =====================================================
        var geminiPayload = {

            contents: [
                {
                    role: 'user',

                    parts: [
                        {
                            text: prompt
                        }
                    ]
                }
            ],

            generationConfig: {

    temperature: 0.2,

    maxOutputTokens: 1500,

    thinkingConfig: {
        thinkingLevel: 'low'
    }

}

        };


        // IMPORTANT:
        // Build JSON safely here.
        // Do NOT use setStringParameterNoEscape for the prompt.
        gemini.setRequestBody(
            JSON.stringify(geminiPayload)
        );


        // =====================================================
        // CALL GEMINI
        // =====================================================
        var geminiResponse =
            gemini.execute();


        var statusCode =
            geminiResponse.getStatusCode();


        var responseBody =
            geminiResponse.getBody();


        gs.info(
            '[SmartAttend AI] Gemini HTTP status=' +
            statusCode
        );


        // =====================================================
        // GEMINI ERROR / FALLBACK
        // =====================================================
        if (
            statusCode < 200 ||
            statusCode >= 300
        ) {

            gs.error(
                '[SmartAttend AI] Gemini HTTP ' +
                statusCode +
                ': ' +
                responseBody
            );


            response.setStatus(200);

            response.setBody({

                success: false,

                fallback: true,

                provider:
                    'Gemini',

                provider_status:
                    statusCode,

                message:
                    'AI service is temporarily unavailable.'

            });

            return;
        }


        // =====================================================
        // PARSE GEMINI RESPONSE
        // =====================================================
        var geminiData =
            JSON.parse(responseBody);


        if (
            !geminiData.candidates ||
            geminiData.candidates.length === 0
        ) {

            response.setStatus(200);

            response.setBody({

                success: false,

                fallback: true,

                message:
                    'AI service returned no recommendation.'

            });

            return;
        }


        var content =
            geminiData.candidates[0].content || {};


        var parts =
            content.parts || [];


        var aiText = '';


        // Gemini can return multiple parts.
        // Collect only actual text.
        for (
            var i = 0;
            i < parts.length;
            i++
        ) {

            if (
                parts[i] &&
                parts[i].text
            ) {

                aiText +=
                    parts[i].text;

            }

        }


        aiText =
            aiText.trim();


        if (!aiText) {

            response.setStatus(200);

            response.setBody({

                success: false,

                fallback: true,

                message:
                    'AI service returned an empty recommendation.'

            });

            return;
        }


        // =====================================================
        // SUCCESS
        // =====================================================
        response.setStatus(200);

        response.setBody({

            success: true,

            provider:
                'Gemini',

            model:
                'gemini-3.6-flash',

            ai_text:
                aiText

        });


    }
    catch (e) {

        gs.error(
            '[SmartAttend AI] Exception: ' +
            e.message
        );


        response.setStatus(200);

        response.setBody({

            success: false,

            fallback: true,

            message:
                'AI recommendation could not be generated.'

        });

    }

})(request, response);
